/**
 * JSON Validator Utility
 *
 * Reads JSON input from stdin, validates it, and outputs the result with status messages.
 *
 * ## Usage
 *
 * Pipe JSON to this script:
 * ```bash
 * echo '{"key": "value"}' | bun run src/json-validator.ts
 * ```
 *
 * ## Input Format
 *
 * Accepts valid JSON as a single line or multiline input via stdin.
 *
 * ## Output Format
 *
 * Success: Prints "Valid JSON" followed by the parsed object on separate line
 * Error: Prints "Invalid JSON: <error reason>" with exit code 1
 *
 * ## Examples
 *
 * Valid JSON:
 * ```
 * $ echo '{"name":"John","age":30}' | bun run src/json-validator.ts
 * Valid JSON
 * { name: 'John', age: 30 }
 * ```
 *
 * Invalid JSON:
 * ```
 * $ echo '{invalid}' | bun run src/json-validator.ts
 * Invalid JSON: Unexpected token 'i', "{invalid}" is not valid JSON
 * ```
 */

/**
 * Reads all input from stdin and returns it as a string.
 */
async function readStdin(): Promise<string> {
  const chunks: Uint8Array[] = [];

  for await (const chunk of Bun.stdin.stream()) {
    chunks.push(chunk);
  }

  const buffer = Buffer.concat(chunks);
  return buffer.toString("utf-8").trim();
}

/**
 * Validates JSON string and returns the parsed object.
 * Throws descriptive error on invalid JSON.
 */
function validateJson(jsonString: string): unknown {
  try {
    return JSON.parse(jsonString);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Unexpected token found: ${message}`);
  }
}

/**
 * Main function that orchestrates reading stdin and validating JSON.
 */
async function main(): Promise<void> {
  try {
    const input = await readStdin();

    if (!input) {
      console.error("Invalid JSON: No input provided");
      process.exit(1);
    }

    const result = validateJson(input);
    console.log("Valid JSON");
    console.log(result);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`Invalid JSON: ${message}`);
    process.exit(1);
  }
}

// Run the validator
main().catch((error) => {
  console.error(`Fatal error: ${error}`);
  process.exit(1);
});

