/**
 * High-performance JSON validator module.
 * Provides utilities for validating JSON structure, types, and schemas.
 */

/**
 * JSON type representation.
 */
export type JSONType = "string" | "number" | "boolean" | "object" | "array" | "null";

/**
 * JSON schema definition for validation.
 */
export interface JSONSchema {
  type?: JSONType | JSONType[];
  required?: string[];
  properties?: Record<string, JSONSchema>;
  items?: JSONSchema;
  minLength?: number;
  maxLength?: number;
  minimum?: number;
  maximum?: number;
  pattern?: string;
}

/**
 * Validation result.
 */
export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

/**
 * Validates if a string is valid JSON.
 * Uses Bun's native JSON parsing with early exit on parse failure.
 *
 * @param json - String to validate as JSON
 * @returns ValidationResult with validity and error details
 */
export function validateJSON(json: string): ValidationResult {
  try {
    JSON.parse(json);
    return { valid: true, errors: [] };
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Unknown JSON parse error";
    return { valid: false, errors: [message] };
  }
}

/**
 * Gets the JSON type of a value.
 *
 * @param value - Value to check
 * @returns JSONType string representation
 */
function getJSONType(value: unknown): JSONType {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return (typeof value) as JSONType;
}

/**
 * Validates a value against a schema with early-exit optimization.
 * Stops validation on first error for better performance.
 *
 * @param value - Value to validate
 * @param schema - JSON schema to validate against
 * @param path - Current path in object hierarchy (for error reporting)
 * @returns ValidationResult with errors if validation fails
 */
export function validateSchema(
  value: unknown,
  schema: JSONSchema,
  path: string = "root"
): ValidationResult {
  const errors: string[] = [];

  // Type validation with early exit
  if (schema.type) {
    const types = Array.isArray(schema.type) ? schema.type : [schema.type];
    const valueType = getJSONType(value);
    if (!types.includes(valueType)) {
      return {
        valid: false,
        errors: [
          `${path}: expected type ${types.join(" | ")}, got ${valueType}`,
        ],
      };
    }
  }

  // Early exit if value is null or not an object/array
  if (value === null || (typeof value !== "object" && !Array.isArray(value))) {
    return { valid: true, errors: [] };
  }

  // Array item validation
  if (Array.isArray(value) && schema.items) {
    for (let i = 0; i < value.length; i++) {
      const itemResult = validateSchema(value[i], schema.items, `${path}[${i}]`);
      if (!itemResult.valid) {
        errors.push(...itemResult.errors);
        return { valid: false, errors }; // Early exit on first error
      }
    }
  }

  // Object properties validation
  if (typeof value === "object" && !Array.isArray(value) && schema.properties) {
    const obj = value as Record<string, unknown>;

    // Check required fields
    if (schema.required) {
      for (const field of schema.required) {
        if (!(field in obj)) {
          return {
            valid: false,
            errors: [`${path}: missing required field "${field}"`],
          };
        }
      }
    }

    // Validate each property
    for (const [key, propSchema] of Object.entries(schema.properties)) {
      if (key in obj) {
        const propResult = validateSchema(
          obj[key],
          propSchema,
          `${path}.${key}`
        );
        if (!propResult.valid) {
          errors.push(...propResult.errors);
          return { valid: false, errors }; // Early exit on first error
        }
      }
    }
  }

  return { valid: true, errors };
}

/**
 * Validates that a value matches the specified JSON type(s).
 * Optimized for quick type checking.
 *
 * @param value - Value to type check
 * @param types - Expected type(s)
 * @returns true if value matches type, false otherwise
 */
export function validateType(
  value: unknown,
  types: JSONType | JSONType[]
): boolean {
  const valueType = getJSONType(value);
  const expectedTypes = Array.isArray(types) ? types : [types];
  return expectedTypes.includes(valueType);
}

import { describe, expect, test } from "bun:test";
import {
  validateJSON,
  validateSchema,
  validateType,
  type JSONSchema,
} from "./json-validator";

describe("JSON Validator", () => {
  describe("validateJSON", () => {
    test("accepts valid JSON string", () => {
      const result = validateJSON('{"key": "value"}');
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("accepts valid JSON array", () => {
      const result = validateJSON('[1, 2, 3]');
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("accepts valid JSON primitives", () => {
      expect(validateJSON('"string"').valid).toBe(true);
      expect(validateJSON("123").valid).toBe(true);
      expect(validateJSON("true").valid).toBe(true);
      expect(validateJSON("null").valid).toBe(true);
    });

    test("rejects invalid JSON with missing quotes", () => {
      const result = validateJSON("{key: value}");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("rejects invalid JSON with trailing comma", () => {
      const result = validateJSON('[1, 2, 3,]');
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("rejects invalid JSON with malformed structure", () => {
      const result = validateJSON('{"unclosed": "object"');
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("handles complex nested valid JSON", () => {
      const complex = JSON.stringify({
        users: [
          { id: 1, name: "Alice", active: true },
          { id: 2, name: "Bob", active: false },
        ],
        metadata: { count: 2, timestamp: "2026-04-11" },
      });
      const result = validateJSON(complex);
      expect(result.valid).toBe(true);
    });
  });

  describe("validateType", () => {
    test("validates string type", () => {
      expect(validateType("hello", "string")).toBe(true);
      expect(validateType(123, "string")).toBe(false);
    });

    test("validates number type", () => {
      expect(validateType(42, "number")).toBe(true);
      expect(validateType(3.14, "number")).toBe(true);
      expect(validateType("42", "number")).toBe(false);
    });

    test("validates boolean type", () => {
      expect(validateType(true, "boolean")).toBe(true);
      expect(validateType(false, "boolean")).toBe(true);
      expect(validateType(1, "boolean")).toBe(false);
    });

    test("validates null type", () => {
      expect(validateType(null, "null")).toBe(true);
      expect(validateType(undefined, "null")).toBe(false);
    });

    test("validates object type", () => {
      expect(validateType({}, "object")).toBe(true);
      expect(validateType({ key: "value" }, "object")).toBe(true);
      expect(validateType([], "object")).toBe(false);
    });

    test("validates array type", () => {
      expect(validateType([], "array")).toBe(true);
      expect(validateType([1, 2, 3], "array")).toBe(true);
      expect(validateType({}, "array")).toBe(false);
    });

    test("validates multiple allowed types", () => {
      expect(validateType("text", ["string", "number"])).toBe(true);
      expect(validateType(42, ["string", "number"])).toBe(true);
      expect(validateType(true, ["string", "number"])).toBe(false);
    });
  });

  describe("validateSchema", () => {
    test("validates simple object schema", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          name: { type: "string" },
          age: { type: "number" },
        },
      };
      const result = validateSchema({ name: "Alice", age: 30 }, schema);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("fails on type mismatch", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          name: { type: "string" },
          age: { type: "number" },
        },
      };
      const result = validateSchema({ name: "Alice", age: "30" }, schema);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("validates required fields", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          id: { type: "number" },
          name: { type: "string" },
        },
        required: ["id", "name"],
      };
      const result = validateSchema({ id: 1 }, schema);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.includes("name"))).toBe(true);
    });

    test("validates array items", () => {
      const schema: JSONSchema = {
        type: "array",
        items: { type: "number" },
      };
      const result = validateSchema([1, 2, 3], schema);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("fails on invalid array items", () => {
      const schema: JSONSchema = {
        type: "array",
        items: { type: "number" },
      };
      const result = validateSchema([1, "two", 3], schema);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("validates nested objects", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          user: {
            type: "object",
            properties: {
              name: { type: "string" },
              email: { type: "string" },
            },
            required: ["name"],
          },
        },
      };
      const result = validateSchema(
        {
          user: {
            name: "Alice",
            email: "alice@example.com",
          },
        },
        schema
      );
      expect(result.valid).toBe(true);
    });

    test("fails on missing nested required field", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          user: {
            type: "object",
            properties: {
              name: { type: "string" },
            },
            required: ["name"],
          },
        },
      };
      const result = validateSchema(
        {
          user: {
            email: "alice@example.com",
          },
        },
        schema
      );
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.includes("name"))).toBe(true);
    });

    test("validates array of objects", () => {
      const schema: JSONSchema = {
        type: "array",
        items: {
          type: "object",
          properties: {
            id: { type: "number" },
            name: { type: "string" },
          },
          required: ["id"],
        },
      };
      const result = validateSchema(
        [
          { id: 1, name: "Alice" },
          { id: 2, name: "Bob" },
        ],
        schema
      );
      expect(result.valid).toBe(true);
    });

    test("fails on invalid items in array of objects", () => {
      const schema: JSONSchema = {
        type: "array",
        items: {
          type: "object",
          properties: {
            id: { type: "number" },
          },
          required: ["id"],
        },
      };
      const result = validateSchema(
        [{ id: 1 }, { name: "Bob" }], // second object missing required 'id'
        schema
      );
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("accepts multiple allowed types", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          value: { type: ["string", "number"] },
        },
      };
      expect(validateSchema({ value: "text" }, schema).valid).toBe(true);
      expect(validateSchema({ value: 42 }, schema).valid).toBe(true);
      expect(validateSchema({ value: true }, schema).valid).toBe(false);
    });

    test("validates null values", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          optional: { type: "null" },
        },
      };
      const result = validateSchema({ optional: null }, schema);
      expect(result.valid).toBe(true);
    });

    test("validates completely null value", () => {
      const schema: JSONSchema = { type: "null" };
      const result = validateSchema(null, schema);
      expect(result.valid).toBe(true);
    });

    test("returns correct error path for deep nested failures", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          level1: {
            type: "object",
            properties: {
              level2: {
                type: "object",
                properties: {
                  value: { type: "string" },
                },
              },
            },
          },
        },
      };
      const result = validateSchema(
        { level1: { level2: { value: 123 } } },
        schema
      );
      expect(result.valid).toBe(false);
      expect(result.errors[0]).toContain("level1.level2.value");
    });

    test("handles empty objects and arrays", () => {
      const objSchema: JSONSchema = { type: "object" };
      const arrSchema: JSONSchema = { type: "array" };
      expect(validateSchema({}, objSchema).valid).toBe(true);
      expect(validateSchema([], arrSchema).valid).toBe(true);
    });
  });
});

